const $ = s => root.querySelector(s);
const $$ = s => [...root.querySelectorAll(s)];
const presets=[{id:'sh600519',name:'贵州茅台'},{id:'sz300750',name:'宁德时代'},{id:'sz000001',name:'平安银行'},{id:'sh601318',name:'中国平安'},{id:'sz002594',name:'比亚迪'}];
const indices=[{id:'sh000001',name:'上证指数'},{id:'sz399001',name:'深证成指'},{id:'sz399006',name:'创业板指'}];
const key='ashare-desk-v1', quotes=new Map(), names=new Map([...presets,...indices].map(x=>[x.id,x.name]));
const events=new AbortController();
let watch=presets.map(x=>({...x})), selected=presets[0], period='minute', adjustment='qfq', chart=null, hover=-1, disposed=false, seq=0, searchSeq=0, searchTimer, busy=false, listBusy=false, lastChart=0, failed=false;
const stockID = x => /^(sh(?:60|68)\d{4}|sz(?:00|30)\d{4}|bj[489]\d{5})$/.test(x);
try {const saved=JSON.parse(localStorage.getItem(key)||'null');if(Array.isArray(saved?.watch))watch=saved.watch.filter(x=>stockID(x?.id)&&typeof x.name==='string').slice(0,30);if(stockID(saved?.selected?.id)||indices.some(x=>x.id===saved?.selected?.id))selected=saved.selected;}catch(_){}
watch.forEach(x=>names.set(x.id,x.name));
function save(){try{localStorage.setItem(key,JSON.stringify({watch,selected}));}catch(_){}}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>x!==null&&x!==undefined&&String(x).trim()!==''&&Number.isFinite(Number(x))?Number(x):null;
const fmt=(x,n=2)=>num(x)===null?'—':Number(x).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n});
const signed=(x,n=2)=>num(x)===null?'—':(Number(x)>0?'+':'')+Number(x).toFixed(n);
const tone=x=>num(x)===null||Number(x)===0?'as-neutral':Number(x)>0?'as-up':'as-down';
const unit=(x,suffix='')=>num(x)===null?'—':Math.abs(x)>=1e8?fmt(x/1e8)+' 亿'+suffix:Math.abs(x)>=1e4?fmt(x/1e4)+' 万'+suffix:fmt(x,0)+suffix;
const dateText=s=>/^\d{8}$/.test(s||'')?s.slice(0,4)+'-'+s.slice(4,6)+'-'+s.slice(6,8):s||'—';
function stamp(s){return /^\d{14}$/.test(s||'')?dateText(s.slice(0,8))+' '+s.slice(8,10)+':'+s.slice(10,12)+':'+s.slice(12,14):'时间未知';}
function status(text,error=false){if(disposed)return;$('.as-status').textContent=text;$('.as-status').classList.toggle('error',error);}
function localTime(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23',weekday:'short'}).formatToParts(new Date());return Object.fromEntries(parts.map(x=>[x.type,x.value]));}
function session(){const t=localTime(),m=Number(t.hour)*60+Number(t.minute),weekday=!['Sat','Sun'].includes(t.weekday);return {t,trading:weekday&&((m>=565&&m<=690)||(m>=780&&m<=900)),label:!weekday?'周末休市':m<565?'盘前':m<=690?'交易时段':m<780?'午间休市':m<=900?'交易时段':'已收盘'};}
function clock(){const {t,label}=session();$('.as-session').textContent=label+' · 北京时间';$('.as-clock').textContent=t.month+'/'+t.day+' '+t.hour+':'+t.minute+':'+t.second;}
async function request(url){const r=await bridge.fetchProxy(url);if(!r?.ok)throw Error(r?.status?'接口 HTTP '+r.status:r?.error||'本地桥接未连接');if(typeof r.data==='string'){try{return JSON.parse(r.data);}catch(_){throw Error('行情格式异常');}}return r.data;}
function parseQuote(id,a){if(!Array.isArray(a)||num(a[3])===null||!/^\d{6}$/.test(a[2]||''))return null;return {id,a,name:names.get(id)||(!/[\ufffd]/.test(a[1])?a[1]:id),price:num(a[3]),prev:num(a[4]),change:num(a[31]),pct:num(a[32]),time:a[30]};}
function setQuote(id,a,utf8=false){if(utf8&&a?.[1])names.set(id,a[1]);const q=parseQuote(id,a);if(q)quotes.set(id,q);return q;}
function renderIndices(){const el=$('.as-indices');el.innerHTML=indices.map(x=>{const q=quotes.get(x.id);return `<button type="button" class="as-index" data-stock="${x.id}"><span class="as-index-name">${x.name}<small class="as-index-code">${x.id.toUpperCase()}</small></span><span class="as-index-value ${tone(q?.pct)}">${fmt(q?.price)}<small class="as-index-change">${signed(q?.change)} &nbsp; ${signed(q?.pct)}%</small></span></button>`;}).join('');}
function renderWatch(){const el=$('.as-watchlist');$('.as-watch-count').textContent=watch.length;el.innerHTML=watch.length?watch.map(x=>{const q=quotes.get(x.id);return `<div class="as-watch-row ${selected.id===x.id?'active':''}"><button type="button" class="as-watch-select" data-stock="${x.id}"><span><strong>${escape(names.get(x.id)||x.name)}</strong><small>${x.id.toUpperCase()}</small></span><span class="as-watch-price ${tone(q?.pct)}"><strong>${fmt(q?.price)}</strong><small>${signed(q?.pct)}%</small></span></button><button type="button" class="as-remove" data-remove="${x.id}" aria-label="移除${escape(x.name)}">×</button></div>`;}).join(''):'<p class="as-empty-watch">搜索一只股票，开始建立自选列表。</p>';renderStar();}
function renderStar(){const on=watch.some(x=>x.id===selected.id),index=indices.some(x=>x.id===selected.id);$('.as-star').textContent=on?'★ 已自选':'☆ 自选';$('.as-star').classList.toggle('selected',on);$('.as-star').disabled=index;$('.as-star').title=index?'指数显示在顶部':'在当前浏览器保存自选';}
