function renderQuote(){const q=quotes.get(selected.id);$('.as-stock-name').textContent=names.get(selected.id)||selected.name;$('.as-stock-code').textContent=selected.id.slice(2)+' · '+({sh:'沪市',sz:'深市',bj:'北交所'}[selected.id.slice(0,2)]||'A股');renderStar();const a=q?.a||[];$('.as-price').textContent=fmt(q?.price);$('.as-price').className='as-price '+tone(q?.pct);$('.as-change').textContent=q?signed(q.change)+'   '+signed(q.pct)+'%':'—';$('.as-change').className='as-change '+tone(q?.pct);$('.as-quote-time').textContent=q?'行情时间 '+stamp(q.time)+'（北京时间）':'正在获取 '+selected.name+' 行情…';$('.as-stats').innerHTML=[stat('今开',fmt(a[5]),tone(num(a[5])-q?.prev)),stat('最高',fmt(a[33]),tone(num(a[33])-q?.prev)),stat('最低',fmt(a[34]),tone(num(a[34])-q?.prev)),stat('昨收',fmt(a[4])),stat('成交量',unit(num(a[6]),'手')),stat('成交额',num(a[37])===null?'—':unit(Number(a[37])*1e4))].join('');$('.as-details').innerHTML=[stat('换手率',num(a[38])===null?'—':fmt(a[38])+'%'),stat('市盈率 TTM',fmt(a[39])),stat('总市值',num(a[45])===null?'—':fmt(a[45])+' 亿'),stat('振幅',num(a[43])===null?'—':fmt(a[43])+'%')].join('');let rows='';for(let i=0;i<5;i++){for(const [label,base] of [['买',9],['卖',19]]){const p=num(a[base+i*2]),v=num(a[base+i*2+1]);rows+=`<div class="as-order"><span>${label}${i+1}</span><span class="${tone(p-q?.prev)}">${p>0?fmt(p):'—'}</span><span>${v>0?fmt(v,0):'—'}</span></div>`;}}$('.as-orders').innerHTML=rows;}
